var IK = window.__IK || (window.__IK = {});
// Column centres and row centres, in % of the scene.
IK.X = [27, 73];
IK.Y = { phone: 14, inst: 44, db: 70 };

IK.scene = function(id){ MSD.cls('.ik-sc', 'on', false); MSD.cls('#ik-sc-' + id, 'on', true); };

IK.strip = function(label, text, tone){
  MSD.cls('#ik-strip', 'bad', tone === 'bad');
  MSD.cls('#ik-strip', 'good', tone === 'good');
  MSD.q('#ik-strip-l').textContent = label;
  MSD.q('#ik-strip-t').textContent = text;
};

IK.phone = function(text, tone){
  MSD.q('#ik-ph-t').textContent = text;
  MSD.cls('#ik-phone', 'bad', tone === 'bad');
  MSD.cls('#ik-phone', 'good', tone === 'good');
};
IK.btn = function(off){ MSD.cls('#ik-btn', 'off', !!off); };
IK.tap = function(){
  MSD.cls('#ik-btn', 'press', true);
  MSD.after(120, function(){ MSD.cls('#ik-btn', 'press', false); });
  MSD.sfx.pop();
};
IK.key = function(on){ MSD.cls('#ik-key', 'on', !!on); };

IK.ar = function(row, i, tone){
  ['live','bad','ok'].forEach(function(c){ MSD.cls('#ik-a' + row + '-' + i, c, tone === c); });
};

IK.inst = function(i, tone, chip, chipTone){
  ['live','ok','bad'].forEach(function(c){ MSD.cls('#ik-in-' + i, c, tone === c); });
  var v = MSD.q('#ik-in-v-' + i);
  v.textContent = chip || 'idle';
  ['ok','bad','warn'].forEach(function(c){ v.classList.toggle(c, chipTone === c); });
};

// One row of dbo.Orders: empty, bad (a duplicate), ok, or reject (bounced).
IK.row = function(i, state, id, text, verdict){
  var el = '#ik-r-' + i;
  ['empty','bad','ok','reject'].forEach(function(c){ MSD.cls(el, c, state === c); });
  MSD.q('#ik-r-id-' + i).textContent = id || '—';
  MSD.q('#ik-r-t-' + i).textContent = text || 'no row';
  MSD.q('#ik-r-v-' + i).textContent = verdict || '';
};
IK.order = 'user 88 · biryani × 1 · ₹410';

IK.db = function(tone, sub){
  ['live','ok','bad'].forEach(function(c){ MSD.cls('#ik-db', c, tone === c); });
  if (sub) MSD.q('#ik-db-s').textContent = sub;
};
IK.pay = function(n, tone){
  var v = MSD.q('#ik-pay');
  v.textContent = '💳 charged × ' + n;
  ['ok','bad','warn'].forEach(function(c){ v.classList.toggle(c, tone === c); });
};

// A request travelling between two rows, in one column.
IK.send = function(col, fromRow, toRow, n){
  var fx = fromRow === 'phone' ? 50 : IK.X[col];
  var tx = toRow === 'phone' ? 50 : IK.X[col];
  MSD.particles('#ik-scene', { from:{ x:fx, y:IK.Y[fromRow] }, to:{ x:tx, y:IK.Y[toRow] }, count:n || 5, duration:650, spread:18 });
};

IK.reset = function(){
  IK.scene('world');
  IK.phone('ready', ''); IK.btn(false); IK.key(false);
  [1,2].forEach(function(i){ IK.ar(1, i, ''); IK.ar(2, i, ''); IK.inst(i, '', 'idle', ''); IK.row(i, 'empty'); });
  IK.db('', 'no rule about repeats');
  IK.pay(0, '');
};

IK.reset();
IK.strip('DOUBLE TAP', 'The customer taps twice, 180 ms apart.', '');

MSD.after(500, function(){ IK.tap(); IK.ar(1, 1, 'live'); IK.send(0, 'phone', 'inst'); IK.inst(1, 'live', 'POST', ''); });
MSD.after(700, function(){ IK.tap(); IK.ar(1, 2, 'live'); IK.send(1, 'phone', 'inst'); IK.inst(2, 'live', 'POST', ''); });
MSD.after(1700, function(){
  IK.ar(2, 1, 'bad'); IK.ar(2, 2, 'bad');
  IK.send(0, 'inst', 'db'); IK.send(1, 'inst', 'db'); MSD.sfx.data(2);
});
MSD.after(2500, function(){ IK.row(1, 'bad', 'o-1041', IK.order, 'new'); MSD.sfx.blip(2); });
MSD.after(2800, function(){ IK.row(2, 'bad', 'o-1042', IK.order, 'new'); MSD.sfx.blip(3); IK.db('bad'); });
MSD.after(3500, function(){
  IK.pay(2, 'bad'); MSD.punch('#ik-pay', 4); MSD.shake('#ik-db');
  IK.strip('CHARGED TWICE', 'Two rows. Two charges. One biryani.', 'bad');
});

